#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
Extract key frames from a video for light-recipe color analysis.

Doubao searches for a scene video (or the user supplies one), then this script
grabs a handful of representative frames — the moments where the picture's
colors change — so the skill can sample the "四周" (four edges) of each frame.

Requires ffmpeg/ffprobe on PATH (or in the usual Homebrew / /usr/local / /usr/bin
locations). If ffmpeg is missing the script fails loudly and the skill falls back
to asking Doubao to supply frames as images.

Usage:
    python3 scripts/video_frames.py <video_url_or_path> [--count 8] [--mode even|scene]
    python3 scripts/video_frames.py clip.mp4 --mode scene --scene-threshold 0.3
    python3 scripts/video_frames.py clip.mp4 --out-dir /tmp/frames --max-width 1280

Output: JSON with {success, video, duration, size, mode, frames:[{index,t,path,...}]}
"""
import json
import os
import shutil
import subprocess
import sys
import tempfile

SEARCH_DIRS = ["/opt/homebrew/bin", "/usr/local/bin", "/usr/bin", "/opt/local/bin", "/snap/bin"]


def find_tool(name):
    """Locate an executable on PATH or in well-known install dirs."""
    found = shutil.which(name)
    if found:
        return found
    for d in SEARCH_DIRS:
        cand = os.path.join(d, name)
        if os.path.exists(cand) and os.access(cand, os.X_OK):
            return cand
    return None


def _run(cmd, timeout=180):
    proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout)
    return proc.returncode, proc.stdout.decode("utf-8", "replace"), proc.stderr.decode("utf-8", "replace")


def probe(video, ffprobe):
    """Return {duration, width, height, fps} for a video (best effort)."""
    cmd = [
        ffprobe, "-v", "error", "-select_streams", "v:0",
        "-show_entries", "stream=width,height,avg_frame_rate,duration",
        "-show_entries", "format=duration",
        "-of", "json", video,
    ]
    code, out, err = _run(cmd, timeout=60)
    if code != 0:
        return {"duration": 0.0, "width": 0, "height": 0, "fps": 0.0, "error": err.strip()[:200]}

    try:
        data = json.loads(out or "{}")
    except json.JSONDecodeError:
        data = {}

    stream = (data.get("streams") or [{}])[0]
    duration = 0.0
    for src in (data.get("format", {}).get("duration"), stream.get("duration")):
        try:
            duration = float(src)
            break
        except (TypeError, ValueError):
            continue

    fps = 0.0
    rate = stream.get("avg_frame_rate") or "0/1"
    try:
        num, den = rate.split("/")
        fps = float(num) / float(den) if float(den) else 0.0
    except (ValueError, ZeroDivisionError):
        fps = 0.0

    return {
        "duration": round(duration, 3),
        "width": int(stream.get("width") or 0),
        "height": int(stream.get("height") or 0),
        "fps": round(fps, 2),
    }


def _frame_brightness(path):
    """Average luminance 0-255 of a frame, or None if unreadable."""
    try:
        from PIL import Image
        with Image.open(path) as img:
            return float(img.convert("L").resize((1, 1)).getpixel((0, 0)))
    except Exception:
        return None


def _scale_filter(max_width):
    if max_width and max_width > 0:
        return "scale='min({},iw)':-2".format(int(max_width))
    return None


def extract_frames_even(video, out_dir, count, ffmpeg, duration, max_width=1280):
    frames = []
    scale = _scale_filter(max_width)
    for i in range(count):
        t = duration * (i + 0.5) / count if duration > 0 else float(i)
        out_path = os.path.join(out_dir, "frame_{:03d}.jpg".format(i))
        cmd = [ffmpeg, "-hide_banner", "-loglevel", "error", "-ss", "{:.3f}".format(t),
               "-i", video, "-frames:v", "1", "-q:v", "2", "-y"]
        if scale:
            cmd += ["-vf", scale]
        cmd.append(out_path)
        code, _, _ = _run(cmd, timeout=120)
        if code == 0 and os.path.exists(out_path) and os.path.getsize(out_path) > 0:
            frames.append({"index": len(frames), "t": round(t, 3), "path": out_path,
                           "brightness": _frame_brightness(out_path)})
    return frames


def extract_frames_scene(video, out_dir, count, ffmpeg, threshold=0.3, max_width=1280):
    """Grab scene-change frames, then thin them down to at most `count`."""
    pattern = os.path.join(out_dir, "scene_%03d.jpg")
    vf = "select='gt(scene,{})'".format(threshold)
    scale = _scale_filter(max_width)
    if scale:
        vf += "," + scale
    cmd = [ffmpeg, "-hide_banner", "-loglevel", "error", "-i", video,
           "-vf", vf, "-vsync", "vfr", "-q:v", "2", "-y", pattern]
    code, _, err = _run(cmd, timeout=300)
    produced = sorted(f for f in os.listdir(out_dir) if f.startswith("scene_") and f.endswith(".jpg"))
    if code != 0 or not produced:
        return [], err.strip()[:200]

    # Keep at most `count`, evenly spaced through the produced list.
    if len(produced) > count:
        step = len(produced) / float(count)
        picked = [produced[min(len(produced) - 1, int(i * step))] for i in range(count)]
    else:
        picked = produced

    frames = []
    for i, fname in enumerate(picked):
        path = os.path.join(out_dir, fname)
        frames.append({"index": i, "t": None, "path": path, "brightness": _frame_brightness(path)})
    return frames, None


def extract_keyframes(video, count=8, mode="even", out_dir=None, max_width=1280,
                      scene_threshold=0.3, min_brightness=20.0):
    """Extract key frames; returns a JSON-serializable result dict."""
    ffmpeg = find_tool("ffmpeg")
    ffprobe = find_tool("ffprobe")
    if not ffmpeg or not ffprobe:
        return {
            "success": False,
            "video": video,
            "message": ("ffmpeg/ffprobe not found. Install ffmpeg, or have Doubao extract "
                        "frames itself and pass image files to analyze_video.py."),
        }

    meta = probe(video, ffprobe)
    if meta.get("width") == 0 and meta.get("error"):
        return {"success": False, "video": video, "message": "ffprobe failed: " + meta["error"],
                "probe": meta}

    created_dir = None
    if not out_dir:
        out_dir = tempfile.mkdtemp(prefix="wled_frames_")
        created_dir = out_dir
    os.makedirs(out_dir, exist_ok=True)

    note = None
    if mode == "scene":
        frames, err = extract_frames_scene(video, out_dir, count, ffmpeg,
                                           threshold=scene_threshold, max_width=max_width)
        if not frames:
            note = "scene detection produced no frames; fell back to even sampling"
            mode = "even"
            frames = extract_frames_even(video, out_dir, count, ffmpeg,
                                         meta.get("duration", 0.0), max_width=max_width)
            if err:
                note += " (ffmpeg: " + err + ")"
    else:
        frames = extract_frames_even(video, out_dir, count, ffmpeg,
                                     meta.get("duration", 0.0), max_width=max_width)

    # Drop near-black frames (fade in/out, title cards) when others survive.
    if min_brightness is not None:
        bright = [f for f in frames if (f.get("brightness") is None or f["brightness"] >= min_brightness)]
        if bright:
            frames = bright

    for i, f in enumerate(frames):
        f["index"] = i

    if not frames:
        return {"success": False, "video": video, "message": "No frames could be extracted",
                "probe": meta, "out_dir": out_dir}

    return {
        "success": True,
        "video": video,
        "duration": meta.get("duration"),
        "width": meta.get("width"),
        "height": meta.get("height"),
        "fps": meta.get("fps"),
        "mode": mode,
        "frame_count": len(frames),
        "out_dir": out_dir,
        "frames": frames,
        "note": note,
        "message": "Extracted {} key frames from {}".format(len(frames), video),
    }


def main():
    if "--help" in sys.argv or "-h" in sys.argv or len(sys.argv) < 2:
        print(__doc__)
        sys.exit(0)

    video = sys.argv[1]
    count = 8
    mode = "even"
    out_dir = None
    max_width = 1280
    scene_threshold = 0.3

    i = 2
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == "--count" and i + 1 < len(sys.argv):
            count = int(sys.argv[i + 1]); i += 2
        elif arg == "--mode" and i + 1 < len(sys.argv):
            mode = sys.argv[i + 1]; i += 2
        elif arg == "--out-dir" and i + 1 < len(sys.argv):
            out_dir = sys.argv[i + 1]; i += 2
        elif arg == "--max-width" and i + 1 < len(sys.argv):
            max_width = int(sys.argv[i + 1]); i += 2
        elif arg == "--scene-threshold" and i + 1 < len(sys.argv):
            scene_threshold = float(sys.argv[i + 1]); i += 2
        else:
            i += 1

    result = extract_keyframes(video, count=count, mode=mode, out_dir=out_dir,
                               max_width=max_width, scene_threshold=scene_threshold)
    print(json.dumps(result, indent=2, ensure_ascii=False))
    sys.exit(0 if result.get("success") else 1)


if __name__ == "__main__":
    main()
# AI: end
